import { readFileSync } from "node:fs";

import { jsonlHistoryStore, toStoredRun } from "../src/data/history.js";
import type { Report } from "../src/scorer/types.js";

/**
 * Bootstraps local history from already-committed, already-verified example
 * reports — not fabricated data. Run once after cloning:
 *   npm run seed-history
 *
 * Deliberately NOT importing examples/maskit-2026-10-07.json: that file's
 * phase field ("quiet") was generated by the inferPhase bug described in
 * HANDOVER.md, fixed the same day. Seeding known-incorrect output into
 * history would be exactly the kind of plausible-but-wrong value this
 * project exists to refuse, even though the underlying stage scores in that
 * file were fine. Only the corrected run is used.
 */
const KNOWN_GOOD_EXAMPLES = ["examples/maskit-2026-10-07-after-phase-fix.json"];

const store = jsonlHistoryStore();

for (const path of KNOWN_GOOD_EXAMPLES) {
  const report = JSON.parse(readFileSync(path, "utf8")) as Report;
  store.record(toStoredRun(report));
  console.log(`seeded ${path} → ${report.symbol ?? report.mint} @ ${report.composite}/100 (${report.phase})`);
}
